// Colour detection as packages do it when they load.
function level(stream, fd) {
  var env = process.env;
  if ("NO_COLOR" in env) return 0;
  if (env.FORCE_COLOR !== undefined) return env.FORCE_COLOR === "0" ? 0 : 3;
  if (!stream.isTTY || !require("tty").isatty(fd)) return 0;
  if (env.TERM === "dumb") return 0;
  if (env.COLORTERM === "truecolor") return 3;
  if (/-256(color)?$/i.test(env.TERM)) return 2;
  return 1;
}
module.exports = { stdout: level(process.stdout, 1), stderr: level(process.stderr, 2) };
